  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In vivo tissue distribution in mice showed the closest analog [11C]14 had only very low brain uptake despite sufficient lipophilicity, indicating inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "For the next closest analog [18F]2a, the brain-to-blood ratio reached only 0.42 over 60 min with limited, slow BBB passage, indicating poor penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "In a human pharmacokinetic study, valdecoxib (active moiety of parecoxib) was detected in CSF within 15 min and remained at 6-14 ng/mL, demonstrating meaningful CNS penetration.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Closest structural analogs show low or limited brain uptake in vivo, supporting fail; positive human CSF evidence from valdecoxib is less similar and does not override the nearest negative transfer.",
  "evidence_gaps": [
    "No direct query-specific brain or CSF measurement was retrieved.",
    "Closest negative evidence comes from radiotracer studies in mice, which may not fully reflect systemic therapeutic dosing.",
    "Positive CNS evidence is from less similar compounds (e.g., valdecoxib, sulfanilamide, toltrazuril sulfone), limiting transferability."
  ],
